tool_use_result.content:
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{
  --color-bg:#fff;--color-bg-alt:#f5f5f7;--color-text:#1d1d1f;
  --color-text-secondary:#6e6e73;--color-link:#0066cc;
  --color-border:#d2d2d7;--nav-h:44px;--ribbon-h:44px;
  --font:-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text","Helvetica Neue",Helvetica,Arial,sans-serif;
  --max-w:1200px;--section-pad:80px 0;
}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--font);color:var(--color-text);background:var(--color-bg);line-height:1.47;font-size:17px;-webkit-font-smoothing:antialiased}
a{color:var(--color-link);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;display:block}
button{font-family:inherit;cursor:pointer;border:none;background:none}
ul{list-style:none}

/* Ribbon */
.ribbon{background:var(--color-bg-alt);text-align:center;padding:12px 20px;font-size:14px;color:var(--color-text-secondary);border-bottom:1px solid var(--color-border)}
.ribbon a{font-size:14px}

/* Nav */
.nav{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.92);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--color-border);height:var(--nav-h);display:flex;align-items:center;justify-content:center}
.nav-inner{max-width:var(--max-w);width:100%;display:flex;align-items:center;justify-content:space-between;padding:0 24px}
.nav-logo{font-size:21px;font-weight:700;color:var(--color-text);letter-spacing:-.5px}
.nav-logo:hover{text-decoration:none}
.nav-links{display:flex;gap:28px;align-items:center}
.nav-links a{font-size:13px;color:var(--color-text);opacity:.8;transition:opacity .2s}
.nav-links a:hover{opacity:1;text-decoration:none}
.nav-links a.active{opacity:1;font-weight:600}
.nav-icons{display:flex;gap:16px;align-items:center}
.nav-icons i{font-size:17px;color:var(--color-text);opacity:.8}
.nav-hamburger{display:none;font-size:20px;color:var(--color-text)}

/* Section */
.section{padding:var(--section-pad)}
.section-inner{max-width:var(--max-w);margin:0 auto;padding:0 24px}
.section-dark{background:var(--color-bg-alt)}
.section-header{margin-bottom:32px}
.section-header h2{font-size:40px;font-weight:700;letter-spacing:-.02em;line-height:1.1}
.section-header p{font-size:19px;color:var(--color-text-secondary);margin-top:8px;font-weight:400}
.section-header .promo{font-size:14px;color:var(--color-text-secondary);margin-top:12px}

/* Hero (homepage) */
.hero{text-align:center;padding:56px 24px 20px;background:var(--color-bg-alt)}
.hero h1{font-size:56px;font-weight:700;letter-spacing:-.03em;line-height:1.05}
.hero p{font-size:24px;color:var(--color-text-secondary);margin-top:12px;font-weight:300}
.hero-ctas{display:flex;gap:20px;justify-content:center;margin-top:20px;flex-wrap:wrap}
.hero-ctas a{font-size:15px;display:inline-flex;align-items:center;gap:4px}
.hero-ctas a i{font-size:14px}

/* Product Grid (homepage) */
.product-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;max-width:var(--max-w);margin:0 auto;padding:16px 24px}
.hero-tile{border-radius:24px;padding:48px 40px 0;text-align:center;min-height:520px;display:flex;flex-direction:column;align-items:center;position:relative;overflow:hidden;transition:transform .3s}
.hero-tile:hover{transform:scale(1.01)}
.hero-tile h2{font-size:40px;font-weight:700;letter-spacing:-.02em;line-height:1.1}
.hero-tile .tagline{font-size:19px;color:var(--color-text-secondary);margin-top:6px;font-weight:400}
.hero-tile .tile-ctas{display:flex;gap:20px;margin-top:16px;justify-content:center}
.hero-tile .tile-ctas a{font-size:15px;display:inline-flex;align-items:center;gap:4px}
.hero-tile .product-img{flex:1;display:flex;align-items:flex-end;justify-content:center;width:100%;margin-top:24px}
.hero-tile .product-img .img-placeholder{width:280px;height:260px;border-radius:20px}

/* Tile Themes */
.tile-phone{background:linear-gradient(180deg,#fafafa 0%,#e8e0f0 100%)}
.tile-laptop-neo{background:linear-gradient(180deg,#f0faf5 0%,#d4edda 100%)}
.tile-tablet-pro{background:linear-gradient(180deg,#fafafa 0%,#e0e8f5 100%)}
.tile-laptop-pro{background:linear-gradient(180deg,#f5f5f7 0%,#d5d5dc 100%)}
.tile-earbuds{background:linear-gradient(180deg,#fafafa 0%,#fde8d0 100%)}
.tile-tradein{background:linear-gradient(180deg,#f0f8f0 0%,#c8e6c9 100%)}
.tile-phone .img-placeholder{background:linear-gradient(135deg,#667eea,#764ba2)}
.tile-laptop-neo .img-placeholder{background:linear-gradient(135deg,#11998e,#38ef7d)}
.tile-tablet-pro .img-placeholder{background:linear-gradient(135deg,#6c5ce7,#a29bfe)}
.tile-laptop-pro .img-placeholder{background:linear-gradient(135deg,#2d3436,#636e72)}
.tile-earbuds .img-placeholder{background:linear-gradient(135deg,#f5af19,#f12711)}
.tile-tradein .img-placeholder{background:linear-gradient(135deg,#00b09b,#96c93d)}

/* Carousel */
.carousel{position:relative}
.carousel-track{display:flex;gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-ms-overflow-style:none;scroll-behavior:smooth;padding:8px 0}
.carousel-track::-webkit-scrollbar{display:none}
.carousel-track>.card{scroll-snap-align:start;flex:0 0 auto}
.carousel-btn{position:absolute;top:50%;transform:translateY(-50%);width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,.9);border:1px solid var(--color-border);display:flex;align-items:center;justify-content:center;z-index:5;font-size:18px;color:var(--color-text);transition:all .2s;box-shadow:0 2px 8px rgba(0,0,0,.1)}
.carousel-btn:hover{background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.15)}
.carousel-btn.prev{left:-16px}
.carousel-btn.next{right:-16px}
.carousel-btn:disabled{opacity:.3;cursor:default}

/* Product Card (carousel) */
.card{background:#fff;border-radius:20px;overflow:hidden;transition:box-shadow .3s}
.card:hover{box-shadow:0 8px 30px rgba(0,0,0,.08)}
.card-product{width:320px;padding:0}
.card-product .card-img{height:260px;display:flex;align-items:center;justify-content:center;position:relative}
.card-product .card-img .img-placeholder{width:180px;height:180px;border-radius:50%}
.card-product .badge{position:absolute;top:16px;left:16px;font-size:11px;font-weight:600;color:var(--color-link);text-transform:uppercase;letter-spacing:.02em}
.card-product .card-body{padding:20px 24px 24px}
.card-product .card-body h3{font-size:21px;font-weight:600;line-height:1.2}
.card-product .card-body .tagline{font-size:14px;color:var(--color-text-secondary);margin-top:4px;line-height:1.4}
.card-product .card-body .price{font-size:15px;margin-top:12px;font-weight:500}
.card-product .card-body .monthly{font-size:13px;color:var(--color-text-secondary);margin-top:2px}

/* Gradient themes for product cards */
.grad-phone17pro{background:linear-gradient(135deg,#e8dff5,#d4c5f0)}
.grad-laptop-neo{background:linear-gradient(135deg,#d4edda,#b5dfca)}
.grad-phone17e{background:linear-gradient(135deg,#fce4ec,#f8bbd0)}
.grad-headphones{background:linear-gradient(135deg,#cfd8dc,#90a4ae)}
.grad-laptop-pro{background:linear-gradient(135deg,#d5d5dc,#b0b0b8)}
.grad-laptop-air{background:linear-gradient(135deg,#e3f2fd,#bbdefb)}
.grad-tablet-air{background:linear-gradient(135deg,#e8eaf6,#c5cae9)}
.grad-watch{background:linear-gradient(135deg,#fff3e0,#ffe0b2)}
.grad-phone17{background:linear-gradient(135deg,#e0f7fa,#b2ebf2)}
.grad-phone-air{background:linear-gradient(135deg,#fce4ec,#f3e5f5)}
.grad-tablet-pro{background:linear-gradient(135deg,#ede7f6,#d1c4e9)}
.grad-tablet{background:linear-gradient(135deg,#e8f5e9,#c8e6c9)}
.grad-tablet-mini{background:linear-gradient(135deg,#fff8e1,#ffecb3)}
.grad-desktop-one{background:linear-gradient(135deg,#eceff1,#cfd8dc)}
.grad-desktop-mini{background:linear-gradient(135deg,#f3e5f5,#e1bee7)}
.grad-desktop-studio{background:linear-gradient(135deg,#263238,#455a64);color:#fff}
.grad-desktop-studio h3,.grad-desktop-studio .tagline,.grad-desktop-studio .price,.grad-desktop-studio .monthly{color:#fff}

/* Accessory/Audio Card */
.card-accessory{width:260px;padding:0}
.card-accessory .card-img{height:200px;display:flex;align-items:center;justify-content:center;background:var(--color-bg-alt)}
.card-accessory .card-img .img-placeholder{width:120px;height:120px;border-radius:16px}
.card-accessory .card-body{padding:16px 20px 20px}
.card-accessory .card-body h3{font-size:15px;font-weight:600;line-height:1.3}
.card-accessory .card-body .price{font-size:14px;margin-top:6px;font-weight:500}
.card-accessory .card-body .note{font-size:12px;color:var(--color-link);margin-top:4px}

/* Accessory gradients */
.grad-case{background:linear-gradient(135deg,#fce4ec,#f8bbd0)}
.grad-strap{background:linear-gradient(135deg,#f8bbd0,#f48fb1)}
.grad-charger{background:linear-gradient(135deg,#eceff1,#cfd8dc)}
.grad-keyboard{background:linear-gradient(135deg,#37474f,#546e7a)}
.grad-battery{background:linear-gradient(135deg,#e8eaf6,#c5cae9)}
.grad-headphones-max{background:linear-gradient(135deg,#1a237e,#283593)}
.grad-earbuds-pro{background:linear-gradient(135deg,#f5f5f5,#e0e0e0)}
.grad-earbuds4{background:linear-gradient(135deg,#fafafa,#eeeeee)}
.grad-powerbuds{background:linear-gradient(135deg,#ff6d00,#ff9100)}
.grad-smartspeaker{background:linear-gradient(135deg,#1a237e,#0d47a1)}
.grad-smartspeaker-mini{background:linear-gradient(135deg,#e65100,#ff6d00)}

/* Info Card (help, store-diff, savings, etc.) */
.card-info{width:280px;padding:32px 28px;display:flex;flex-direction:column;background:var(--color-bg-alt);border-radius:20px}
.card-info i{font-size:32px;color:var(--color-link);margin-bottom:16px}
.card-info h3{font-size:19px;font-weight:600;line-height:1.3}
.card-info p{font-size:14px;color:var(--color-text-secondary);margin-top:8px;line-height:1.5;flex:1}
.card-info a.card-link{font-size:14px;margin-top:16px;display:inline-flex;align-items:center;gap:4px}

/* Product Icon Bar (store page) */
.product-bar{padding:24px 0;overflow-x:auto;scrollbar-width:none}
.product-bar::-webkit-scrollbar{display:none}
.product-bar-inner{display:flex;gap:32px;justify-content:center;align-items:center;min-width:max-content;padding:0 24px}
.product-icon{display:flex;flex-direction:column;align-items:center;gap:8px;text-decoration:none;color:var(--color-text);transition:opacity .2s;min-width:70px}
.product-icon:hover{opacity:.7;text-decoration:none}
.product-icon .icon-circle{width:64px;height:64px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;color:#fff}
.product-icon span{font-size:12px;font-weight:500}

/* Icon circle colors */
.ic-laptop{background:linear-gradient(135deg,#667eea,#764ba2)}
.ic-phone{background:linear-gradient(135deg,#f093fb,#f5576c)}
.ic-tablet{background:linear-gradient(135deg,#4facfe,#00f2fe)}
.ic-watch{background:linear-gradient(135deg,#fa709a,#fee140)}
.ic-headphones{background:linear-gradient(135deg,#a18cd1,#fbc2eb)}
.ic-accessories{background:linear-gradient(135deg,#fccb90,#d57eeb)}

/* Brand Collab */
.collab{border-radius:24px;padding:60px 48px;text-align:center;background:linear-gradient(135deg,#1a1a2e,#16213e);color:#fff;margin:0 auto;max-width:var(--max-w)}
.collab h2{font-size:36px;font-weight:700;letter-spacing:-.02em}
.collab p{font-size:18px;opacity:.8;margin-top:8px}
.collab .collab-items{display:flex;gap:24px;justify-content:center;margin-top:32px;flex-wrap:wrap}
.collab .collab-item{background:rgba(255,255,255,.1);border-radius:16px;padding:20px 24px;min-width:160px}
.collab .collab-item span{font-size:14px;opacity:.9}

/* Entertainment Tabs */
.ent-tabs{display:flex;gap:12px;margin-bottom:24px;flex-wrap:wrap}
.ent-tab{padding:10px 24px;border-radius:100px;font-size:15px;font-weight:500;background:var(--color-bg-alt);color:var(--color-text-secondary);border:1px solid transparent;transition:all .2s}
.ent-tab.active{background:var(--color-text);color:#fff}
.ent-tab:hover{border-color:var(--color-border)}
.ent-panel{display:none}
.ent-panel.active{display:block}
.ent-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}
.ent-card{border-radius:20px;padding:24px;min-height:180px;display:flex;flex-direction:column;justify-content:flex-end;position:relative;overflow:hidden}
.ent-card h4{font-size:17px;font-weight:600;color:#fff;position:relative;z-index:1}
.ent-card p{font-size:13px;color:rgba(255,255,255,.8);margin-top:4px;position:relative;z-index:1}
.ent-card a{font-size:13px;color:#fff;margin-top:10px;display:inline-flex;align-items:center;gap:4px;position:relative;z-index:1}
.ent-card a:hover{color:#fff}
.ent-stream1{background:linear-gradient(135deg,#0f0c29,#302b63,#24243e)}
.ent-stream2{background:linear-gradient(135deg,#141e30,#243b55)}
.ent-stream3{background:linear-gradient(135deg,#1a1a2e,#e94560)}
.ent-stream4{background:linear-gradient(135deg,#0f2027,#203a43,#2c5364)}
.ent-fitness1{background:linear-gradient(135deg,#11998e,#38ef7d)}
.ent-fitness2{background:linear-gradient(135deg,#fc4a1a,#f7b733)}
.ent-fitness3{background:linear-gradient(135deg,#e44d26,#f16529)}
.ent-fitness4{background:linear-gradient(135deg,#56ab2f,#a8e063)}
.ent-gaming1{background:linear-gradient(135deg,#6c5ce7,#a29bfe)}
.ent-gaming2{background:linear-gradient(135deg,#e44d26,#9b59b6)}
.ent-gaming3{background:linear-gradient(135deg,#0c3547,#3a7bd5)}
.ent-gaming4{background:linear-gradient(135deg,#2d3436,#636e72)}
.ent-music1{background:linear-gradient(135deg,#fa709a,#fee140)}
.ent-music2{background:linear-gradient(135deg,#a18cd1,#fbc2eb)}
.ent-music3{background:linear-gradient(135deg,#f093fb,#f5576c)}
.ent-music4{background:linear-gradient(135deg,#4facfe,#00f2fe)}

/* Quick Links */
.quick-links{display:flex;gap:12px;flex-wrap:wrap;justify-content:center}
.quick-link{padding:10px 24px;border-radius:100px;font-size:14px;font-weight:500;background:var(--color-bg-alt);color:var(--color-text);border:1px solid var(--color-border);transition:all .2s}
.quick-link:hover{background:var(--color-text);color:#fff;text-decoration:none;border-color:var(--color-text)}

/* Section Nav (category pages) */
.section-nav{position:sticky;top:var(--nav-h);z-index:90;background:rgba(255,255,255,.92);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--color-border);overflow-x:auto;scrollbar-width:none}
.section-nav::-webkit-scrollbar{display:none}
.section-nav-inner{display:flex;gap:0;max-width:var(--max-w);margin:0 auto;padding:0 24px;min-width:max-content}
.section-nav a{padding:14px 20px;font-size:13px;color:var(--color-text-secondary);white-space:nowrap;transition:color .2s;display:block;border-bottom:2px solid transparent}
.section-nav a:hover{color:var(--color-text);text-decoration:none}
.section-nav a.active{color:var(--color-text);font-weight:600;border-bottom-color:var(--color-text)}

/* Category Hero */
.cat-hero{text-align:center;padding:60px 24px 40px;background:var(--color-bg-alt)}
.cat-hero h1{font-size:48px;font-weight:700;letter-spacing:-.03em;line-height:1.1}
.cat-hero p{font-size:21px;color:var(--color-text-secondary);margin-top:10px;font-weight:300}

/* Store Hero */
.store-hero{text-align:center;padding:60px 24px 32px}
.store-hero h1{font-size:56px;font-weight:700;letter-spacing:-.03em;line-height:1.05}
.store-hero p{font-size:24px;color:var(--color-text-secondary);margin-top:10px;font-weight:300}
.store-hero .hero-links{display:flex;gap:24px;justify-content:center;margin-top:20px;flex-wrap:wrap}
.store-hero .hero-links a{font-size:15px;display:inline-flex;align-items:center;gap:4px}

/* Shopping Guide / Savings cards */
.card-guide{width:260px;padding:0;border-radius:20px;overflow:hidden;background:var(--color-bg-alt)}
.card-guide .card-img{height:160px;display:flex;align-items:center;justify-content:center}
.card-guide .card-body{padding:20px 24px 24px}
.card-guide .card-body h3{font-size:17px;font-weight:600;line-height:1.3}
.card-guide .card-body p{font-size:13px;color:var(--color-text-secondary);margin-top:6px;line-height:1.5}
.card-guide .card-body a{font-size:13px;margin-top:10px;display:inline-flex;align-items:center;gap:4px}
.grad-guide1{background:linear-gradient(135deg,#667eea,#764ba2)}
.grad-guide2{background:linear-gradient(135deg,#f093fb,#f5576c)}
.grad-guide3{background:linear-gradient(135deg,#4facfe,#00f2fe)}
.grad-guide4{background:linear-gradient(135deg,#fa709a,#fee140)}
.grad-guide5{background:linear-gradient(135deg,#11998e,#38ef7d)}
.grad-save1{background:linear-gradient(135deg,#00b09b,#96c93d)}
.grad-save2{background:linear-gradient(135deg,#667eea,#764ba2)}
.grad-save3{background:linear-gradient(135deg,#f5af19,#f12711)}
.grad-save4{background:linear-gradient(135deg,#a18cd1,#fbc2eb)}
.grad-save5{background:linear-gradient(135deg,#0c3547,#2e5c7a)}
.grad-special1{background:linear-gradient(135deg,#f093fb,#f5576c)}
.grad-special2{background:linear-gradient(135deg,#4facfe,#00f2fe)}
.grad-special3{background:linear-gradient(135deg,#a18cd1,#fbc2eb)}
.grad-special4{background:linear-gradient(135deg,#667eea,#764ba2)}
.grad-special5{background:linear-gradient(135deg,#11998e,#38ef7d)}
.grad-special6{background:linear-gradient(135deg,#fa709a,#fee140)}

/* Footer */
.footer{background:var(--color-bg-alt);padding:40px 0 24px;border-top:1px solid var(--color-border);margin-top:40px}
.footer-inner{max-width:var(--max-w);margin:0 auto;padding:0 24px}
.footer-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:24px}
.footer-section h4{font-size:13px;font-weight:600;margin-bottom:12px;color:var(--color-text)}
.footer-section a{display:block;font-size:12px;color:var(--color-text-secondary);line-height:2;transition:color .2s}
.footer-section a:hover{color:var(--color-text);text-decoration:none}
.footer-section .accordion-toggle{display:none;width:100%;text-align:left;font-size:13px;font-weight:600;color:var(--color-text);padding:12px 0;border-bottom:1px solid var(--color-border);justify-content:space-between;align-items:center}
.footer-section .accordion-toggle i{transition:transform .3s;font-size:14px}
.footer-section .accordion-toggle.open i{transform:rotate(180deg)}
.footer-bottom{border-top:1px solid var(--color-border);margin-top:32px;padding-top:20px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}
.footer-bottom p{font-size:12px;color:var(--color-text-secondary)}
.footer-legal{max-width:var(--max-w);margin:0 auto;padding:24px 24px 0;font-size:11px;color:var(--color-text-secondary);line-height:1.6}

/* Responsive */
@media(max-width:1024px){
  .product-grid{grid-template-columns:1fr 1fr;gap:12px;padding:12px 16px}
  .hero-tile{min-height:420px;padding:36px 28px 0}
  .hero-tile h2{font-size:32px}
  .section-header h2{font-size:32px}
  .hero h1,.store-hero h1{font-size:44px}
  .cat-hero h1{font-size:40px}
}
@media(max-width:768px){
  .product-grid{grid-template-columns:1fr;gap:12px;padding:12px 16px}
  .hero-tile{min-height:380px;padding:32px 24px 0}
  .hero-tile h2{font-size:28px}
  .nav-links{display:none}
  .nav-hamburger{display:block}
  .section{padding:48px 0}
  .section-header h2{font-size:28px}
  .hero h1,.store-hero h1{font-size:36px}
  .hero p,.store-hero p{font-size:19px}
  .cat-hero h1{font-size:32px}
  .footer-grid{grid-template-columns:1fr}
  .footer-section h4{display:none}
  .footer-section .accordion-toggle{display:flex}
  .footer-section .footer-links{display:none}
  .footer-section .footer-links.open{display:block;padding-bottom:8px}
  .ent-grid{grid-template-columns:1fr 1fr}
  .collab{padding:40px 24px}
  .collab h2{font-size:28px}
  .carousel-btn.prev{left:4px}
  .carousel-btn.next{right:4px}
}
@media(max-width:480px){
  .hero h1,.store-hero h1{font-size:28px}
  .hero p,.store-hero p{font-size:17px}
  .cat-hero h1{font-size:26px}
  .hero-tile{min-height:320px}
  .hero-tile h2{font-size:24px}
  .ent-grid{grid-template-columns:1fr}
  .card-product{width:280px}
  .card-accessory{width:220px}
  .card-info{width:260px}
  .card-guide{width:240px}
}

*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{
  --color-bg:#fff;--color-bg-alt:#f5f5f7;--color-text:#1d1d1f;
  --color-text-secondary:#6e6e73;--color-link:#0066cc;
  --color-border:#d2d2d7;--nav-h:44px;--ribbon-h:44px;
  --font:-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text","Helvetica Neue",Helvetica,Arial,sans-serif;
  --max-w:1200px;--section-pad:80px 0;
}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--font);color:var(--color-text);background:var(--color-bg);line-height:1.47;font-size:17px;-webkit-font-smoothing:antialiased}
a{color:var(--color-link);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;display:block}
button{font-family:inherit;cursor:pointer;border:none;background:none}
ul{list-style:none}

/* Ribbon */
.ribbon{background:var(--color-bg-alt);text-align:center;padding:12px 20px;font-size:14px;color:var(--color-text-secondary);border-bottom:1px solid var(--color-border)}
.ribbon a{font-size:14px}

/* Nav */
.nav{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.92);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--color-border);height:var(--nav-h);display:flex;align-items:center;justify-content:center}
.nav-inner{max-width:var(--max-w);width:100%;display:flex;align-items:center;justify-content:space-between;padding:0 24px}
.nav-logo{font-size:21px;font-weight:700;color:var(--color-text);letter-spacing:-.5px}
.nav-logo:hover{text-decoration:none}
.nav-links{display:flex;gap:28px;align-items:center}
.nav-links a{font-size:13px;color:var(--color-text);opacity:.8;transition:opacity .2s}
.nav-links a:hover{opacity:1;text-decoration:none}
.nav-links a.active{opacity:1;font-weight:600}
.nav-icons{display:flex;gap:16px;align-items:center}
.nav-icons i{font-size:17px;color:var(--color-text);opacity:.8}
.nav-hamburger{display:none;font-size:20px;color:var(--color-text)}

/* Section */
.section{padding:var(--section-pad)}
.section-inner{max-width:var(--max-w);margin:0 auto;padding:0 24px}
.section-dark{background:var(--color-bg-alt)}
.section-header{margin-bottom:32px}
.section-header h2{font-size:40px;font-weight:700;letter-spacing:-.02em;line-height:1.1}
.section-header p{font-size:19px;color:var(--color-text-secondary);margin-top:8px;font-weight:400}
.section-header .promo{font-size:14px;color:var(--color-text-secondary);margin-top:12px}

/* Hero (homepage) */
.hero{text-align:center;padding:56px 24px 20px;background:var(--color-bg-alt)}
.hero h1{font-size:56px;font-weight:700;letter-spacing:-.03em;line-height:1.05}
.hero p{font-size:24px;color:var(--color-text-secondary);margin-top:12px;font-weight:300}
.hero-ctas{display:flex;gap:20px;justify-content:center;margin-top:20px;flex-wrap:wrap}
.hero-ctas a{font-size:15px;display:inline-flex;align-items:center;gap:4px}
.hero-ctas a i{font-size:14px}

/* Product Grid (homepage) */
.product-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;max-width:var(--max-w);margin:0 auto;padding:16px 24px}
.hero-tile{border-radius:24px;padding:48px 40px 0;text-align:center;min-height:520px;display:flex;flex-direction:column;align-items:center;position:relative;overflow:hidden;transition:transform .3s}
.hero-tile:hover{transform:scale(1.01)}
.hero-tile h2{font-size:40px;font-weight:700;letter-spacing:-.02em;line-height:1.1}
.hero-tile .tagline{font-size:19px;color:var(--color-text-secondary);margin-top:6px;font-weight:400}
.hero-tile .tile-ctas{display:flex;gap:20px;margin-top:16px;justify-content:center}
.hero-tile .tile-ctas a{font-size:15px;display:inline-flex;align-items:center;gap:4px}
.hero-tile .product-img{flex:1;display:flex;align-items:flex-end;justify-content:center;width:100%;margin-top:24px}
.hero-tile .product-img .img-placeholder{width:280px;height:260px;border-radius:20px}

/* Tile Themes */
.tile-phone{background:linear-gradient(180deg,#fafafa 0%,#e8e0f0 100%)}
.tile-laptop-neo{background:linear-gradient(180deg,#f0faf5 0%,#d4edda 100%)}
.tile-tablet-pro{background:linear-gradient(180deg,#fafafa 0%,#e0e8f5 100%)}
.tile-laptop-pro{background:linear-gradient(180deg,#f5f5f7 0%,#d5d5dc 100%)}
.tile-earbuds{background:linear-gradient(180deg,#fafafa 0%,#fde8d0 100%)}
.tile-tradein{background:linear-gradient(180deg,#f0f8f0 0%,#c8e6c9 100%)}
.tile-phone .img-placeholder{background:linear-gradient(135deg,#667eea,#764ba2)}
.tile-laptop-neo .img-placeholder{background:linear-gradient(135deg,#11998e,#38ef7d)}
.tile-tablet-pro .img-placeholder{background:linear-gradient(135deg,#6c5ce7,#a29bfe)}
.tile-laptop-pro .img-placeholder{background:linear-gradient(135deg,#2d3436,#636e72)}
.tile-earbuds .img-placeholder{background:linear-gradient(135deg,#f5af19,#f12711)}
.tile-tradein .img-placeholder{background:linear-gradient(135deg,#00b09b,#96c93d)}

/* Carousel */
.carousel{position:relative}
.carousel-track{display:flex;gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-ms-overflow-style:none;scroll-behavior:smooth;padding:8px 0}
.carousel-track::-webkit-scrollbar{display:none}
.carousel-track>.card{scroll-snap-align:start;flex:0 0 auto}
.carousel-btn{position:absolute;top:50%;transform:translateY(-50%);width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,.9);border:1px solid var(--color-border);display:flex;align-items:center;justify-content:center;z-index:5;font-size:18px;color:var(--color-text);transition:all .2s;box-shadow:0 2px 8px rgba(0,0,0,.1)}
.carousel-btn:hover{background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.15)}
.carousel-btn.prev{left:-16px}
.carousel-btn.next{right:-16px}
.carousel-btn:disabled{opacity:.3;cursor:default}

/* Product Card (carousel) */
.card{background:#fff;border-radius:20px;overflow:hidden;transition:box-shadow .3s}
.card:hover{box-shadow:0 8px 30px rgba(0,0,0,.08)}
.card-product{width:320px;padding:0}
.card-product .card-img{height:260px;display:flex;align-items:center;justify-content:center;position:relative}
.card-product .card-img .img-placeholder{width:180px;height:180px;border-radius:50%}
.card-product .badge{position:absolute;top:16px;left:16px;font-size:11px;font-weight:600;color:var(--color-link);text-transform:uppercase;letter-spacing:.02em}
.card-product .card-body{padding:20px 24px 24px}
.card-product .card-body h3{font-size:21px;font-weight:600;line-height:1.2}
.card-product .card-body .tagline{font-size:14px;color:var(--color-text-secondary);margin-top:4px;line-height:1.4}
.card-product .card-body .price{font-size:15px;margin-top:12px;font-weight:500}
.card-product .card-body .monthly{font-size:13px;color:var(--color-text-secondary);margin-top:2px}

/* Gradient themes for product cards */
.grad-phone17pro{background:linear-gradient(135deg,#e8dff5,#d4c5f0)}
.grad-laptop-neo{background:linear-gradient(135deg,#d4edda,#b5dfca)}
.grad-phone17e{background:linear-gradient(135deg,#fce4ec,#f8bbd0)}
.grad-headphones{background:linear-gradient(135deg,#cfd8dc,#90a4ae)}
.grad-laptop-pro{background:linear-gradient(135deg,#d5d5dc,#b0b0b8)}
.grad-laptop-air{background:linear-gradient(135deg,#e3f2fd,#bbdefb)}
.grad-tablet-air{background:linear-gradient(135deg,#e8eaf6,#c5cae9)}
.grad-watch{background:linear-gradient(135deg,#fff3e0,#ffe0b2)}
.grad-phone17{background:linear-gradient(135deg,#e0f7fa,#b2ebf2)}
.grad-phone-air{background:linear-gradient(135deg,#fce4ec,#f3e5f5)}
.grad-tablet-pro{background:linear-gradient(135deg,#ede7f6,#d1c4e9)}
.grad-tablet{background:linear-gradient(135deg,#e8f5e9,#c8e6c9)}
.grad-tablet-mini{background:linear-gradient(135deg,#fff8e1,#ffecb3)}
.grad-desktop-one{background:linear-gradient(135deg,#eceff1,#cfd8dc)}
.grad-desktop-mini{background:linear-gradient(135deg,#f3e5f5,#e1bee7)}
.grad-desktop-studio{background:linear-gradient(135deg,#263238,#455a64);color:#fff}
.grad-desktop-studio h3,.grad-desktop-studio .tagline,.grad-desktop-studio .price,.grad-desktop-studio .monthly{color:#fff}

/* Accessory/Audio Card */
.card-accessory{width:260px;padding:0}
.card-accessory .card-img{height:200px;display:flex;align-items:center;justify-content:center;background:var(--color-bg-alt)}
.card-accessory .card-img .img-placeholder{width:120px;height:120px;border-radius:16px}
.card-accessory .card-body{padding:16px 20px 20px}
.card-accessory .card-body h3{font-size:15px;font-weight:600;line-height:1.3}
.card-accessory .card-body .price{font-size:14px;margin-top:6px;font-weight:500}
.card-accessory .card-body .note{font-size:12px;color:var(--color-link);margin-top:4px}

/* Accessory gradients */
.grad-case{background:linear-gradient(135deg,#fce4ec,#f8bbd0)}
.grad-strap{background:linear-gradient(135deg,#f8bbd0,#f48fb1)}
.grad-charger{background:linear-gradient(135deg,#eceff1,#cfd8dc)}
.grad-keyboard{background:linear-gradient(135deg,#37474f,#546e7a)}
.grad-battery{background:linear-gradient(135deg,#e8eaf6,#c5cae9)}
.grad-headphones-max{background:linear-gradient(135deg,#1a237e,#283593)}
.grad-earbuds-pro{background:linear-gradient(135deg,#f5f5f5,#e0e0e0)}
.grad-earbuds4{background:linear-gradient(135deg,#fafafa,#eeeeee)}
.grad-powerbuds{background:linear-gradient(135deg,#ff6d00,#ff9100)}
.grad-smartspeaker{background:linear-gradient(135deg,#1a237e,#0d47a1)}
.grad-smartspeaker-mini{background:linear-gradient(135deg,#e65100,#ff6d00)}

/* Info Card (help, store-diff, savings, etc.) */
.card-info{width:280px;padding:32px 28px;display:flex;flex-direction:column;background:var(--color-bg-alt);border-radius:20px}
.card-info i{font-size:32px;color:var(--color-link);margin-bottom:16px}
.card-info h3{font-size:19px;font-weight:600;line-height:1.3}
.card-info p{font-size:14px;color:var(--color-text-secondary);margin-top:8px;line-height:1.5;flex:1}
.card-info a.card-link{font-size:14px;margin-top:16px;display:inline-flex;align-items:center;gap:4px}

/* Product Icon Bar (store page) */
.product-bar{padding:24px 0;overflow-x:auto;scrollbar-width:none}
.product-bar::-webkit-scrollbar{display:none}
.product-bar-inner{display:flex;gap:32px;justify-content:center;align-items:center;min-width:max-content;padding:0 24px}
.product-icon{display:flex;flex-direction:column;align-items:center;gap:8px;text-decoration:none;color:var(--color-text);transition:opacity .2s;min-width:70px}
.product-icon:hover{opacity:.7;text-decoration:none}
.product-icon .icon-circle{width:64px;height:64px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;color:#fff}
.product-icon span{font-size:12px;font-weight:500}

/* Icon circle colors */
.ic-laptop{background:linear-gradient(135deg,#667eea,#764ba2)}
.ic-phone{background:linear-gradient(135deg,#f093fb,#f5576c)}
.ic-tablet{background:linear-gradient(135deg,#4facfe,#00f2fe)}
.ic-watch{background:linear-gradient(135deg,#fa709a,#fee140)}
.ic-headphones{background:linear-gradient(135deg,#a18cd1,#fbc2eb)}
.ic-accessories{background:linear-gradient(135deg,#fccb90,#d57eeb)}

/* Brand Collab */
.collab{border-radius:24px;padding:60px 48px;text-align:center;background:linear-gradient(135deg,#1a1a2e,#16213e);color:#fff;margin:0 auto;max-width:var(--max-w)}
.collab h2{font-size:36px;font-weight:700;letter-spacing:-.02em}
.collab p{font-size:18px;opacity:.8;margin-top:8px}
.collab .collab-items{display:flex;gap:24px;justify-content:center;margin-top:32px;flex-wrap:wrap}
.collab .collab-item{background:rgba(255,255,255,.1);border-radius:16px;padding:20px 24px;min-width:160px}
.collab .collab-item span{font-size:14px;opacity:.9}

/* Entertainment Tabs */
.ent-tabs{display:flex;gap:12px;margin-bottom:24px;flex-wrap:wrap}
.ent-tab{padding:10px 24px;border-radius:100px;font-size:15px;font-weight:500;background:var(--color-bg-alt);color:var(--color-text-secondary);border:1px solid transparent;transition:all .2s}
.ent-tab.active{background:var(--color-text);color:#fff}
.ent-tab:hover{border-color:var(--color-border)}
.ent-panel{display:none}
.ent-panel.active{display:block}
.ent-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}
.ent-card{border-radius:20px;padding:24px;min-height:180px;display:flex;flex-direction:column;justify-content:flex-end;position:relative;overflow:hidden}
.ent-card h4{font-size:17px;font-weight:600;color:#fff;position:relative;z-index:1}
.ent-card p{font-size:13px;color:rgba(255,255,255,.8);margin-top:4px;position:relative;z-index:1}
.ent-card a{font-size:13px;color:#fff;margin-top:10px;display:inline-flex;align-items:center;gap:4px;position:relative;z-index:1}
.ent-card a:hover{color:#fff}
.ent-stream1{background:linear-gradient(135deg,#0f0c29,#302b63,#24243e)}
.ent-stream2{background:linear-gradient(135deg,#141e30,#243b55)}
.ent-stream3{background:linear-gradient(135deg,#1a1a2e,#e94560)}
.ent-stream4{background:linear-gradient(135deg,#0f2027,#203a43,#2c5364)}
.ent-fitness1{background:linear-gradient(135deg,#11998e,#38ef7d)}
.ent-fitness2{background:linear-gradient(135deg,#fc4a1a,#f7b733)}
.ent-fitness3{background:linear-gradient(135deg,#e44d26,#f16529)}
.ent-fitness4{background:linear-gradient(135deg,#56ab2f,#a8e063)}
.ent-gaming1{background:linear-gradient(135deg,#6c5ce7,#a29bfe)}
.ent-gaming2{background:linear-gradient(135deg,#e44d26,#9b59b6)}
.ent-gaming3{background:linear-gradient(135deg,#0c3547,#3a7bd5)}
.ent-gaming4{background:linear-gradient(135deg,#2d3436,#636e72)}
.ent-music1{background:linear-gradient(135deg,#fa709a,#fee140)}
.ent-music2{background:linear-gradient(135deg,#a18cd1,#fbc2eb)}
.ent-music3{background:linear-gradient(135deg,#f093fb,#f5576c)}
.ent-music4{background:linear-gradient(135deg,#4facfe,#00f2fe)}

/* Quick Links */
.quick-links{display:flex;gap:12px;flex-wrap:wrap;justify-content:center}
.quick-link{padding:10px 24px;border-radius:100px;font-size:14px;font-weight:500;background:var(--color-bg-alt);color:var(--color-text);border:1px solid var(--color-border);transition:all .2s}
.quick-link:hover{background:var(--color-text);color:#fff;text-decoration:none;border-color:var(--color-text)}

/* Section Nav (category pages) */
.section-nav{position:sticky;top:var(--nav-h);z-index:90;background:rgba(255,255,255,.92);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--color-border);overflow-x:auto;scrollbar-width:none}
.section-nav::-webkit-scrollbar{display:none}
.section-nav-inner{display:flex;gap:0;max-width:var(--max-w);margin:0 auto;padding:0 24px;min-width:max-content}
.section-nav a{padding:14px 20px;font-size:13px;color:var(--color-text-secondary);white-space:nowrap;transition:color .2s;display:block;border-bottom:2px solid transparent}
.section-nav a:hover{color:var(--color-text);text-decoration:none}
.section-nav a.active{color:var(--color-text);font-weight:600;border-bottom-color:var(--color-text)}

/* Category Hero */
.cat-hero{text-align:center;padding:60px 24px 40px;background:var(--color-bg-alt)}
.cat-hero h1{font-size:48px;font-weight:700;letter-spacing:-.03em;line-height:1.1}
.cat-hero p{font-size:21px;color:var(--color-text-secondary);margin-top:10px;font-weight:300}

/* Store Hero */
.store-hero{text-align:center;padding:60px 24px 32px}
.store-hero h1{font-size:56px;font-weight:700;letter-spacing:-.03em;line-height:1.05}
.store-hero p{font-size:24px;color:var(--color-text-secondary);margin-top:10px;font-weight:300}
.store-hero .hero-links{display:flex;gap:24px;justify-content:center;margin-top:20px;flex-wrap:wrap}
.store-hero .hero-links a{font-size:15px;display:inline-flex;align-items:center;gap:4px}

/* Shopping Guide / Savings cards */
.card-guide{width:260px;padding:0;border-radius:20px;overflow:hidden;background:var(--color-bg-alt)}
.card-guide .card-img{height:160px;display:flex;align-items:center;justify-content:center}
.card-guide .card-body{padding:20px 24px 24px}
.card-guide .card-body h3{font-size:17px;font-weight:600;line-height:1.3}
.card-guide .card-body p{font-size:13px;color:var(--color-text-secondary);margin-top:6px;line-height:1.5}
.card-guide .card-body a{font-size:13px;margin-top:10px;display:inline-flex;align-items:center;gap:4px}
.grad-guide1{background:linear-gradient(135deg,#667eea,#764ba2)}
.grad-guide2{background:linear-gradient(135deg,#f093fb,#f5576c)}
.grad-guide3{background:linear-gradient(135deg,#4facfe,#00f2fe)}
.grad-guide4{background:linear-gradient(135deg,#fa709a,#fee140)}
.grad-guide5{background:linear-gradient(135deg,#11998e,#38ef7d)}
.grad-save1{background:linear-gradient(135deg,#00b09b,#96c93d)}
.grad-save2{background:linear-gradient(135deg,#667eea,#764ba2)}
.grad-save3{background:linear-gradient(135deg,#f5af19,#f12711)}
.grad-save4{background:linear-gradient(135deg,#a18cd1,#fbc2eb)}
.grad-save5{background:linear-gradient(135deg,#0c3547,#2e5c7a)}
.grad-special1{background:linear-gradient(135deg,#f093fb,#f5576c)}
.grad-special2{background:linear-gradient(135deg,#4facfe,#00f2fe)}
.grad-special3{background:linear-gradient(135deg,#a18cd1,#fbc2eb)}
.grad-special4{background:linear-gradient(135deg,#667eea,#764ba2)}
.grad-special5{background:linear-gradient(135deg,#11998e,#38ef7d)}
.grad-special6{background:linear-gradient(135deg,#fa709a,#fee140)}

/* Footer */
.footer{background:var(--color-bg-alt);padding:40px 0 24px;border-top:1px solid var(--color-border);margin-top:40px}
.footer-inner{max-width:var(--max-w);margin:0 auto;padding:0 24px}
.footer-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:24px}
.footer-section h4{font-size:13px;font-weight:600;margin-bottom:12px;color:var(--color-text)}
.footer-section a{display:block;font-size:12px;color:var(--color-text-secondary);line-height:2;transition:color .2s}
.footer-section a:hover{color:var(--color-text);text-decoration:none}
.footer-section .accordion-toggle{display:none;width:100%;text-align:left;font-size:13px;font-weight:600;color:var(--color-text);padding:12px 0;border-bottom:1px solid var(--color-border);justify-content:space-between;align-items:center}
.footer-section .accordion-toggle i{transition:transform .3s;font-size:14px}
.footer-section .accordion-toggle.open i{transform:rotate(180deg)}
.footer-bottom{border-top:1px solid var(--color-border);margin-top:32px;padding-top:20px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}
.footer-bottom p{font-size:12px;color:var(--color-text-secondary)}
.footer-legal{max-width:var(--max-w);margin:0 auto;padding:24px 24px 0;font-size:11px;color:var(--color-text-secondary);line-height:1.6}

/* Responsive */
@media(max-width:1024px){
  .product-grid{grid-template-columns:1fr 1fr;gap:12px;padding:12px 16px}
  .hero-tile{min-height:420px;padding:36px 28px 0}
  .hero-tile h2{font-size:32px}
  .section-header h2{font-size:32px}
  .hero h1,.store-hero h1{font-size:44px}
  .cat-hero h1{font-size:40px}
}
@media(max-width:768px){
  .product-grid{grid-template-columns:1fr;gap:12px;padding:12px 16px}
  .hero-tile{min-height:380px;padding:32px 24px 0}
  .hero-tile h2{font-size:28px}
  .nav-links{display:none}
  .nav-hamburger{display:block}
  .section{padding:48px 0}
  .section-header h2{font-size:28px}
  .hero h1,.store-hero h1{font-size:36px}
  .hero p,.store-hero p{font-size:19px}
  .cat-hero h1{font-size:32px}
  .footer-grid{grid-template-columns:1fr}
  .footer-section h4{display:none}
  .footer-section .accordion-toggle{display:flex}
  .footer-section .footer-links{display:none}
  .footer-section .footer-links.open{display:block;padding-bottom:8px}
  .ent-grid{grid-template-columns:1fr 1fr}
  .collab{padding:40px 24px}
  .collab h2{font-size:28px}
  .carousel-btn.prev{left:4px}
  .carousel-btn.next{right:4px}
}
@media(max-width:480px){
  .hero h1,.store-hero h1{font-size:28px}
  .hero p,.store-hero p{font-size:17px}
  .cat-hero h1{font-size:26px}
  .hero-tile{min-height:320px}
  .hero-tile h2{font-size:24px}
  .ent-grid{grid-template-columns:1fr}
  .card-product{width:280px}
  .card-accessory{width:220px}
  .card-info{width:260px}
  .card-guide{width:240px}
}

raw_arguments.content:
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{
  --color-bg:#fff;--color-bg-alt:#f5f5f7;--color-text:#1d1d1f;
  --color-text-secondary:#6e6e73;--color-link:#0066cc;
  --color-border:#d2d2d7;--nav-h:44px;--ribbon-h:44px;
  --font:-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text","Helvetica Neue",Helvetica,Arial,sans-serif;
  --max-w:1200px;--section-pad:80px 0;
}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--font);color:var(--color-text);background:var(--color-bg);line-height:1.47;font-size:17px;-webkit-font-smoothing:antialiased}
a{color:var(--color-link);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;display:block}
button{font-family:inherit;cursor:pointer;border:none;background:none}
ul{list-style:none}

/* Ribbon */
.ribbon{background:var(--color-bg-alt);text-align:center;padding:12px 20px;font-size:14px;color:var(--color-text-secondary);border-bottom:1px solid var(--color-border)}
.ribbon a{font-size:14px}

/* Nav */
.nav{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.92);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--color-border);height:var(--nav-h);display:flex;align-items:center;justify-content:center}
.nav-inner{max-width:var(--max-w);width:100%;display:flex;align-items:center;justify-content:space-between;padding:0 24px}
.nav-logo{font-size:21px;font-weight:700;color:var(--color-text);letter-spacing:-.5px}
.nav-logo:hover{text-decoration:none}
.nav-links{display:flex;gap:28px;align-items:center}
.nav-links a{font-size:13px;color:var(--color-text);opacity:.8;transition:opacity .2s}
.nav-links a:hover{opacity:1;text-decoration:none}
.nav-links a.active{opacity:1;font-weight:600}
.nav-icons{display:flex;gap:16px;align-items:center}
.nav-icons i{font-size:17px;color:var(--color-text);opacity:.8}
.nav-hamburger{display:none;font-size:20px;color:var(--color-text)}

/* Section */
.section{padding:var(--section-pad)}
.section-inner{max-width:var(--max-w);margin:0 auto;padding:0 24px}
.section-dark{background:var(--color-bg-alt)}
.section-header{margin-bottom:32px}
.section-header h2{font-size:40px;font-weight:700;letter-spacing:-.02em;line-height:1.1}
.section-header p{font-size:19px;color:var(--color-text-secondary);margin-top:8px;font-weight:400}
.section-header .promo{font-size:14px;color:var(--color-text-secondary);margin-top:12px}

/* Hero (homepage) */
.hero{text-align:center;padding:56px 24px 20px;background:var(--color-bg-alt)}
.hero h1{font-size:56px;font-weight:700;letter-spacing:-.03em;line-height:1.05}
.hero p{font-size:24px;color:var(--color-text-secondary);margin-top:12px;font-weight:300}
.hero-ctas{display:flex;gap:20px;justify-content:center;margin-top:20px;flex-wrap:wrap}
.hero-ctas a{font-size:15px;display:inline-flex;align-items:center;gap:4px}
.hero-ctas a i{font-size:14px}

/* Product Grid (homepage) */
.product-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;max-width:var(--max-w);margin:0 auto;padding:16px 24px}
.hero-tile{border-radius:24px;padding:48px 40px 0;text-align:center;min-height:520px;display:flex;flex-direction:column;align-items:center;position:relative;overflow:hidden;transition:transform .3s}
.hero-tile:hover{transform:scale(1.01)}
.hero-tile h2{font-size:40px;font-weight:700;letter-spacing:-.02em;line-height:1.1}
.hero-tile .tagline{font-size:19px;color:var(--color-text-secondary);margin-top:6px;font-weight:400}
.hero-tile .tile-ctas{display:flex;gap:20px;margin-top:16px;justify-content:center}
.hero-tile .tile-ctas a{font-size:15px;display:inline-flex;align-items:center;gap:4px}
.hero-tile .product-img{flex:1;display:flex;align-items:flex-end;justify-content:center;width:100%;margin-top:24px}
.hero-tile .product-img .img-placeholder{width:280px;height:260px;border-radius:20px}

/* Tile Themes */
.tile-phone{background:linear-gradient(180deg,#fafafa 0%,#e8e0f0 100%)}
.tile-laptop-neo{background:linear-gradient(180deg,#f0faf5 0%,#d4edda 100%)}
.tile-tablet-pro{background:linear-gradient(180deg,#fafafa 0%,#e0e8f5 100%)}
.tile-laptop-pro{background:linear-gradient(180deg,#f5f5f7 0%,#d5d5dc 100%)}
.tile-earbuds{background:linear-gradient(180deg,#fafafa 0%,#fde8d0 100%)}
.tile-tradein{background:linear-gradient(180deg,#f0f8f0 0%,#c8e6c9 100%)}
.tile-phone .img-placeholder{background:linear-gradient(135deg,#667eea,#764ba2)}
.tile-laptop-neo .img-placeholder{background:linear-gradient(135deg,#11998e,#38ef7d)}
.tile-tablet-pro .img-placeholder{background:linear-gradient(135deg,#6c5ce7,#a29bfe)}
.tile-laptop-pro .img-placeholder{background:linear-gradient(135deg,#2d3436,#636e72)}
.tile-earbuds .img-placeholder{background:linear-gradient(135deg,#f5af19,#f12711)}
.tile-tradein .img-placeholder{background:linear-gradient(135deg,#00b09b,#96c93d)}

/* Carousel */
.carousel{position:relative}
.carousel-track{display:flex;gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-ms-overflow-style:none;scroll-behavior:smooth;padding:8px 0}
.carousel-track::-webkit-scrollbar{display:none}
.carousel-track>.card{scroll-snap-align:start;flex:0 0 auto}
.carousel-btn{position:absolute;top:50%;transform:translateY(-50%);width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,.9);border:1px solid var(--color-border);display:flex;align-items:center;justify-content:center;z-index:5;font-size:18px;color:var(--color-text);transition:all .2s;box-shadow:0 2px 8px rgba(0,0,0,.1)}
.carousel-btn:hover{background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.15)}
.carousel-btn.prev{left:-16px}
.carousel-btn.next{right:-16px}
.carousel-btn:disabled{opacity:.3;cursor:default}

/* Product Card (carousel) */
.card{background:#fff;border-radius:20px;overflow:hidden;transition:box-shadow .3s}
.card:hover{box-shadow:0 8px 30px rgba(0,0,0,.08)}
.card-product{width:320px;padding:0}
.card-product .card-img{height:260px;display:flex;align-items:center;justify-content:center;position:relative}
.card-product .card-img .img-placeholder{width:180px;height:180px;border-radius:50%}
.card-product .badge{position:absolute;top:16px;left:16px;font-size:11px;font-weight:600;color:var(--color-link);text-transform:uppercase;letter-spacing:.02em}
.card-product .card-body{padding:20px 24px 24px}
.card-product .card-body h3{font-size:21px;font-weight:600;line-height:1.2}
.card-product .card-body .tagline{font-size:14px;color:var(--color-text-secondary);margin-top:4px;line-height:1.4}
.card-product .card-body .price{font-size:15px;margin-top:12px;font-weight:500}
.card-product .card-body .monthly{font-size:13px;color:var(--color-text-secondary);margin-top:2px}

/* Gradient themes for product cards */
.grad-phone17pro{background:linear-gradient(135deg,#e8dff5,#d4c5f0)}
.grad-laptop-neo{background:linear-gradient(135deg,#d4edda,#b5dfca)}
.grad-phone17e{background:linear-gradient(135deg,#fce4ec,#f8bbd0)}
.grad-headphones{background:linear-gradient(135deg,#cfd8dc,#90a4ae)}
.grad-laptop-pro{background:linear-gradient(135deg,#d5d5dc,#b0b0b8)}
.grad-laptop-air{background:linear-gradient(135deg,#e3f2fd,#bbdefb)}
.grad-tablet-air{background:linear-gradient(135deg,#e8eaf6,#c5cae9)}
.grad-watch{background:linear-gradient(135deg,#fff3e0,#ffe0b2)}
.grad-phone17{background:linear-gradient(135deg,#e0f7fa,#b2ebf2)}
.grad-phone-air{background:linear-gradient(135deg,#fce4ec,#f3e5f5)}
.grad-tablet-pro{background:linear-gradient(135deg,#ede7f6,#d1c4e9)}
.grad-tablet{background:linear-gradient(135deg,#e8f5e9,#c8e6c9)}
.grad-tablet-mini{background:linear-gradient(135deg,#fff8e1,#ffecb3)}
.grad-desktop-one{background:linear-gradient(135deg,#eceff1,#cfd8dc)}
.grad-desktop-mini{background:linear-gradient(135deg,#f3e5f5,#e1bee7)}
.grad-desktop-studio{background:linear-gradient(135deg,#263238,#455a64);color:#fff}
.grad-desktop-studio h3,.grad-desktop-studio .tagline,.grad-desktop-studio .price,.grad-desktop-studio .monthly{color:#fff}

/* Accessory/Audio Card */
.card-accessory{width:260px;padding:0}
.card-accessory .card-img{height:200px;display:flex;align-items:center;justify-content:center;background:var(--color-bg-alt)}
.card-accessory .card-img .img-placeholder{width:120px;height:120px;border-radius:16px}
.card-accessory .card-body{padding:16px 20px 20px}
.card-accessory .card-body h3{font-size:15px;font-weight:600;line-height:1.3}
.card-accessory .card-body .price{font-size:14px;margin-top:6px;font-weight:500}
.card-accessory .card-body .note{font-size:12px;color:var(--color-link);margin-top:4px}

/* Accessory gradients */
.grad-case{background:linear-gradient(135deg,#fce4ec,#f8bbd0)}
.grad-strap{background:linear-gradient(135deg,#f8bbd0,#f48fb1)}
.grad-charger{background:linear-gradient(135deg,#eceff1,#cfd8dc)}
.grad-keyboard{background:linear-gradient(135deg,#37474f,#546e7a)}
.grad-battery{background:linear-gradient(135deg,#e8eaf6,#c5cae9)}
.grad-headphones-max{background:linear-gradient(135deg,#1a237e,#283593)}
.grad-earbuds-pro{background:linear-gradient(135deg,#f5f5f5,#e0e0e0)}
.grad-earbuds4{background:linear-gradient(135deg,#fafafa,#eeeeee)}
